<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { RouterLink } from "vue-router";
import FolioIcon from "../components/FolioIcon.vue";
import { formatLocal, responseError, unwrapPayload } from "./guadao_shared";

type SpecialRule={id?:string|number;marketHashName:string;displayName?:string|null;maxRatioPct:number;currentRatioPct?:number|null;currentRatioObservedAt?:string|null;enabled:boolean;version?:number;updatedAt?:string|null};
type TimePolicy={scanMinutes:number;steamSyncSeconds:number;steamSyncMaxStartLagSeconds:number;staleListedCheckHours:number;actionConfirmSeconds:number[];soldEvidenceMinutes:number[];rebuyMinutes:number[];deliveryMinutes:number[];staleListedRecheckHours:number|null;staleListedMaxRatioTolerancePct:number|null};
type AuditRecord={id?:string|number;at?:string;actor?:string;summary?:string;changes?:string;oldValue?:unknown;newValue?:unknown;diff?:unknown};
type Settings={runtime?:{enabled?:boolean;status?:string};global:{maxListingRatioPct:number;steamNetFactorPct?:number|null;maxNewListingsPerCycle?:number|null;caseMaxOpenCount?:number|null;autoListing:boolean;autoRebuy:boolean;lastModifiedAt?:string|null};specialRules:SpecialRule[];timePolicy:TimePolicy;rawTaskSchedule:Record<string,unknown>;steamScheduler?:{mode?:string;accountRouteCooldownSeconds?:number;globalCooldownSeconds?:number;degradedAfterSeconds?:number;degradedProbeSeconds?:number;quietWindowEnabled?:boolean;respectRetryAfter?:boolean;adaptiveCooldown?:boolean};audit?:AuditRecord[]};
type ItemSuggestion={marketHashName:string;displayName?:string|null;name?:string|null;nameCn?:string|null};
type RawSettings=Record<string,unknown>;
const settings=ref<Settings|null>(null);const loading=ref(false);const saving=ref(false);const error=ref("");const notice=ref("");const dirty=ref(false);const confirmSave=ref(false);const search=ref("");const suggestions=ref<ItemSuggestion[]>([]);const searching=ref(false);const searchHasMore=ref(false);const searchNextOffset=ref(0);let searchTimer:ReturnType<typeof setTimeout>|null=null;
const ratioWarning=computed(()=>Boolean(settings.value?.specialRules.some(rule=>rule.enabled&&rule.maxRatioPct>75)));
const validation=computed(()=>{const s=settings.value;if(!s)return["策略尚未加载"];const errors:string[]=[];if(!(s.global.maxListingRatioPct>0&&s.global.maxListingRatioPct<=80))errors.push("全局最大挂刀比例必须大于 0 且不超过 80%");for(const rule of s.specialRules){if(!rule.marketHashName.trim())errors.push("特殊规则缺少 marketHashName");if(!(rule.maxRatioPct>0))errors.push(`${rule.marketHashName} 的专用上限必须大于 0`);if(rule.maxRatioPct>80)errors.push(`${rule.marketHashName} 的专用上限不能超过 80%`)}if(s.timePolicy.scanMinutes<1)errors.push("完整扫描不得低于 1 分钟");if(s.timePolicy.steamSyncSeconds<30)errors.push("普通 Steam 同步不得低于 30 秒");if(s.timePolicy.steamSyncMaxStartLagSeconds<1)errors.push("Steam 同步最长等待不得低于 1 秒");if(s.timePolicy.staleListedCheckHours<1)errors.push("老挂单候选扫描不得低于 1 小时");if(s.timePolicy.actionConfirmSeconds.some(v=>v<2))errors.push("动作确认不得低于 2 秒");if(s.timePolicy.soldEvidenceMinutes.some(v=>v<0))errors.push("卖出证据复核间隔不能为负数");if(s.timePolicy.rebuyMinutes.some(v=>v<.5)||s.timePolicy.deliveryMinutes.some(v=>v<.5))errors.push("C5 复查不得低于 30 秒");const sequences=[s.timePolicy.actionConfirmSeconds,s.timePolicy.soldEvidenceMinutes,s.timePolicy.rebuyMinutes,s.timePolicy.deliveryMinutes];if(sequences.some(values=>values.some((value,index)=>index>0&&value<values[index-1])))errors.push("多段退避时间必须非递减");return errors});
function numeric(value:unknown,fallback=0):number{const parsed=Number(value);return Number.isFinite(parsed)?parsed:fallback}
function durationLabel(seconds?:number):string{if(seconds==null)return"—";if(seconds%3600===0)return`${seconds/3600} 小时`;if(seconds%60===0)return`${seconds/60} 分钟`;return`${seconds} 秒`}
function auditText(value:unknown):string{if(value==null)return"—";const text=typeof value==="string"?value:JSON.stringify(value);return text.length>120?`${text.slice(0,117)}…`:text}
function adaptSettings(raw:RawSettings):Settings{const task=(raw.taskSchedule&&typeof raw.taskSchedule==="object"?raw.taskSchedule:{}) as Record<string,unknown>;const nestedGlobal=(raw.global&&typeof raw.global==="object"?raw.global:{}) as RawSettings;const rules=(Array.isArray(raw.specialRules)?raw.specialRules:Array.isArray(raw.specialCaseRatioRules)?raw.specialCaseRatioRules:[]) as RawSettings[];const audit=(Array.isArray(raw.audit)?raw.audit:[]) as RawSettings[];const tierMinutes=(key:string)=>((Array.isArray(task[key])?task[key]:[]) as RawSettings[]).map(tier=>numeric(tier.intervalSeconds)/60);return{runtime:(raw.runtime||undefined) as Settings["runtime"],global:{maxListingRatioPct:nestedGlobal.maxListingRatioPct==null?numeric(raw.guadaoMaxListingRatio)*100:numeric(nestedGlobal.maxListingRatioPct),steamNetFactorPct:nestedGlobal.steamNetFactorPct==null?(raw.steamNetFactor==null?null:numeric(raw.steamNetFactor)*100):numeric(nestedGlobal.steamNetFactorPct),maxNewListingsPerCycle:nestedGlobal.maxNewListingsPerCycle==null?(raw.maxNewListingsPerCycle==null?null:numeric(raw.maxNewListingsPerCycle)):numeric(nestedGlobal.maxNewListingsPerCycle),caseMaxOpenCount:nestedGlobal.caseMaxOpenCount==null?(raw.caseMaxOpenCount==null?null:numeric(raw.caseMaxOpenCount)):numeric(nestedGlobal.caseMaxOpenCount),autoListing:nestedGlobal.autoListing==null?Boolean(raw.autoListEnabled):Boolean(nestedGlobal.autoListing),autoRebuy:nestedGlobal.autoRebuy==null?Boolean(raw.autoRebuyEnabled):Boolean(nestedGlobal.autoRebuy),lastModifiedAt:String(nestedGlobal.lastModifiedAt||"")||null},specialRules:rules.map(rule=>({id:String(rule.id||rule.ruleId||""),marketHashName:String(rule.marketHashName||""),displayName:String(rule.displayName||rule.nameCn||"")||null,maxRatioPct:rule.maxRatioPct==null?numeric(rule.maxListingRatio)*100:numeric(rule.maxRatioPct),currentRatioPct:rule.currentRatioPct==null?null:numeric(rule.currentRatioPct),currentRatioObservedAt:String(rule.currentRatioObservedAt||"")||null,enabled:rule.enabled!==false,version:numeric(rule.version,1),updatedAt:String(rule.updatedAt||"")||null})),timePolicy:{scanMinutes:numeric(task.scanIntervalSeconds)/60,steamSyncSeconds:numeric(task.steamSyncIntervalSeconds),steamSyncMaxStartLagSeconds:numeric(task.steamSyncMaxStartLagSeconds,60),staleListedCheckHours:numeric(task.staleListedCheckIntervalSeconds,86400)/3600,actionConfirmSeconds:(Array.isArray(task.actionConfirmationDelaysSeconds)?task.actionConfirmationDelaysSeconds:[]).map(value=>numeric(value)),soldEvidenceMinutes:(Array.isArray(task.saleEvidenceDelaysSeconds)?task.saleEvidenceDelaysSeconds:[]).map(value=>numeric(value)/60),rebuyMinutes:tierMinutes("rebuyRetryTiers"),deliveryMinutes:tierMinutes("deliveryConfirmationTiers"),staleListedRecheckHours:raw.staleListedRecheckHours==null?null:numeric(raw.staleListedRecheckHours),staleListedMaxRatioTolerancePct:raw.staleListedMaxRatioTolerancePct==null?null:numeric(raw.staleListedMaxRatioTolerancePct)},rawTaskSchedule:JSON.parse(JSON.stringify(task)),steamScheduler:(raw.steamScheduler||undefined) as Settings["steamScheduler"],audit:audit.map(row=>({id:String(row.id||""),at:String(row.createdAt||row.at||""),actor:String(row.actor||""),summary:String(row.reason||row.summary||""),changes:row.diff?JSON.stringify(row.diff):String(row.changes||""),oldValue:row.oldValue,newValue:row.newValue,diff:row.diff}))}}
async function load():Promise<void>{loading.value=true;try{const response=await fetch("/api/guadao/settings",{cache:"no-store"});if(!response.ok)throw new Error(await responseError(response));settings.value=adaptSettings(unwrapPayload<RawSettings>(await response.json(),"settings"));dirty.value=false;error.value="";}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{loading.value=false}}
function changed():void{dirty.value=true;notice.value=""}
async function save():Promise<void>{if(!settings.value||validation.value.length)return;const current=settings.value;const rawTask={...current.rawTaskSchedule,scanIntervalSeconds:current.timePolicy.scanMinutes*60,steamSyncIntervalSeconds:current.timePolicy.steamSyncSeconds,steamSyncMaxStartLagSeconds:current.timePolicy.steamSyncMaxStartLagSeconds,staleListedCheckIntervalSeconds:current.timePolicy.staleListedCheckHours*3600,actionConfirmationDelaysSeconds:current.timePolicy.actionConfirmSeconds,saleEvidenceDelaysSeconds:current.timePolicy.soldEvidenceMinutes.map(value=>value*60)} as Record<string,unknown>;const rebuyRaw=(Array.isArray(rawTask.rebuyRetryTiers)?rawTask.rebuyRetryTiers:[]) as RawSettings[];const deliveryRaw=(Array.isArray(rawTask.deliveryConfirmationTiers)?rawTask.deliveryConfirmationTiers:[]) as RawSettings[];rawTask.rebuyRetryTiers=current.timePolicy.rebuyMinutes.map((value,index)=>({...rebuyRaw[index],intervalSeconds:value*60}));rawTask.deliveryConfirmationTiers=current.timePolicy.deliveryMinutes.map((value,index)=>({...deliveryRaw[index],intervalSeconds:value*60}));const body={guadaoMaxListingRatio:current.global.maxListingRatioPct/100,autoListEnabled:current.global.autoListing,autoRebuyEnabled:current.global.autoRebuy,maxListPerCycle:current.global.maxNewListingsPerCycle,caseMaxOpenGuadaoCount:current.global.caseMaxOpenCount,staleListedRecheckHours:current.timePolicy.staleListedRecheckHours,staleListedMaxRatioTolerancePct:current.timePolicy.staleListedMaxRatioTolerancePct,specialCaseRatioRules:current.specialRules.map(rule=>({ruleId:rule.id,version:rule.version,marketHashName:rule.marketHashName,nameCn:rule.displayName,maxListingRatio:rule.maxRatioPct/100,enabled:rule.enabled})),taskSchedule:rawTask,confirmHighRatio:ratioWarning.value};saving.value=true;try{const response=await fetch("/api/guadao/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});if(!response.ok)throw new Error(await responseError(response));settings.value=adaptSettings(unwrapPayload<RawSettings>(await response.json(),"settings"));dirty.value=false;confirmSave.value=false;notice.value="策略已保存；已开启流水继续使用开单时冻结值，修改只影响未来流水。";error.value="";}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{saving.value=false}}
function requestSave():void{if(validation.value.length){error.value=validation.value.join("；");return}confirmSave.value=true}
watch(search,value=>{if(searchTimer)clearTimeout(searchTimer);suggestions.value=[];searchHasMore.value=false;searchNextOffset.value=0;if(value.trim().length<2)return;searchTimer=setTimeout(()=>void findItems(value.trim()),300)});
async function findItems(query:string,append=false):Promise<void>{searching.value=true;try{const offset=append?searchNextOffset.value:0;const response=await fetch(`/api/guadao/items/search?q=${encodeURIComponent(query)}&limit=12&offset=${offset}`,{cache:"no-store"});if(!response.ok)throw new Error(await responseError(response));const payload=unwrapPayload<{items?:ItemSuggestion[];pagination?:{hasMore?:boolean;nextOffset?:number|null}} | ItemSuggestion[]>(await response.json());const incoming=Array.isArray(payload)?payload:payload.items||[];if(query!==search.value.trim())return;if(append){const merged=new Map(suggestions.value.map(item=>[item.marketHashName,item]));for(const item of incoming)merged.set(item.marketHashName,item);suggestions.value=[...merged.values()]}else suggestions.value=incoming;if(!Array.isArray(payload)){searchHasMore.value=Boolean(payload.pagination?.hasMore);searchNextOffset.value=Number(payload.pagination?.nextOffset??0)}}catch(reason){error.value=`物品搜索失败：${reason instanceof Error?reason.message:String(reason)}`}finally{searching.value=false}}
function addRule(item:ItemSuggestion):void{if(!settings.value)return;if(settings.value.specialRules.some(rule=>rule.marketHashName===item.marketHashName)){search.value="";suggestions.value=[];searchHasMore.value=false;return}settings.value.specialRules.push({marketHashName:item.marketHashName,displayName:item.displayName||item.nameCn||item.name||null,maxRatioPct:settings.value.global.maxListingRatioPct,enabled:true});search.value="";suggestions.value=[];searchHasMore.value=false;changed()}
function removeRule(index:number):void{settings.value?.specialRules.splice(index,1);changed()}
onMounted(load);
</script>

<template>
  <main class="page settings-page">
    <header class="settings-heading"><div><p class="eyebrow">Guadao Operations</p><h1>挂刀策略设置</h1><p>配置新挂刀边界与任务时间策略；已开启流水继续使用开单时冻结值</p></div><div class="runtime-card"><span></span><div><strong>挂刀执行器{{settings?.runtime?.enabled?"当前运行中":"当前已关闭"}}</strong><RouterLink to="/guadao/overview">前往运行总览控制</RouterLink></div></div></header>
    <p v-if="error" class="feedback error">{{error}}</p><p v-else-if="notice" class="feedback success">{{notice}}</p><div v-if="loading&&!settings" class="empty-state">正在读取后端策略…</div>
    <template v-if="settings"><section class="settings-grid"><div class="left-column"><article class="panel settings-card"><div class="card-title"><b>1</b><h2>全局执行边界</h2></div><div class="field-grid">
          <label><span>全局最大挂刀比例<br><small>最近修改 {{formatLocal(settings.global.lastModifiedAt)}}</small></span><div><input v-model.number="settings.global.maxListingRatioPct" type="number" min="0.01" max="80" step="0.01" @input="changed" /><em>%</em></div></label>
          <label><span>Steam 税后因子</span><div><input :value="settings.global.steamNetFactorPct ?? ''" type="number" disabled /><em>%</em></div></label>
          <label><span>每轮最大新上架</span><input v-model.number="settings.global.maxNewListingsPerCycle" type="number" min="0" step="1" @input="changed" /></label>
          <label><span>箱子最大活跃挂单</span><input v-model.number="settings.global.caseMaxOpenCount" type="number" min="1" step="1" @input="changed" /></label>
          <label class="toggle-row"><span>自动上架</span><button type="button" :class="['mini-switch',{on:settings.global.autoListing}]" @click="settings.global.autoListing=!settings.global.autoListing;changed()"><i></i>{{settings.global.autoListing?"ON":"OFF"}}</button></label>
          <label class="toggle-row"><span>自动补仓</span><button type="button" :class="['mini-switch',{on:settings.global.autoRebuy}]" @click="settings.global.autoRebuy=!settings.global.autoRebuy;changed()"><i></i>{{settings.global.autoRebuy?"ON":"OFF"}}</button></label>
        </div><div class="frozen-note"><FolioIcon name="warning" :size="14" />设置只影响未来新开流水；已开启流水继续使用 listingRatioAtOpen / maxRebuyRatioAtOpen 等冻结字段。</div></article>
        <article class="panel settings-card special-card">
          <div class="card-title"><b>2</b><h2>特殊箱子最大比例</h2></div>
          <p>按中文名或 marketHashName 模糊搜索，最终按精确 marketHashName 保存与执行。</p>
          <div class="item-search">
            <FolioIcon name="scan" :size="15" />
            <input v-model="search" placeholder="输入物品中文名或 marketHashName" />
            <span v-if="searching">搜索中…</span>
            <div v-if="suggestions.length" class="suggestions">
              <button v-for="item in suggestions" :key="item.marketHashName" type="button" @click="addRule(item)">
                <strong>{{item.displayName||item.nameCn||item.name||item.marketHashName}}</strong>
                <small>{{item.marketHashName}}</small>
              </button>
              <button v-if="searchHasMore" class="catalog-load-more" type="button" :disabled="searching" @click="findItems(search.trim(),true)">{{searching?"加载中…":"加载更多结果"}}</button>
            </div>
          </div>
          <div v-if="settings.specialRules.length" class="rules-table">
            <div class="rule-head"><span>启用</span><span>物品</span><span>全局上限</span><span>专用上限</span><span>最近观测</span><span>版本</span><span>最近修改</span><span></span></div>
            <div v-for="(rule,index) in settings.specialRules" :key="rule.id||rule.marketHashName" class="rule-row">
              <button type="button" :class="['tiny-switch',{on:rule.enabled}]" @click="rule.enabled=!rule.enabled;changed()"><i></i></button>
              <div><strong>{{rule.displayName||rule.marketHashName}}</strong><small>{{rule.marketHashName}}</small></div>
              <span>{{settings.global.maxListingRatioPct.toFixed(2)}}%</span>
              <label><input v-model.number="rule.maxRatioPct" type="number" min="0.01" max="80" step="0.01" @input="changed" />%</label>
              <span><strong>{{rule.currentRatioPct==null?"—":`${rule.currentRatioPct.toFixed(2)}%`}}</strong><small>{{formatLocal(rule.currentRatioObservedAt)}}</small></span>
              <span>v{{rule.version||"—"}}</span><time>{{formatLocal(rule.updatedAt)}}</time><button class="text-danger" type="button" @click="removeRule(index)">移除</button>
            </div>
          </div>
          <div v-else class="empty-state compact">当前没有特殊箱子规则；未设置的物品使用全局最大挂刀比例。</div>
          <div class="rule-note"><FolioIcon name="success" :size="13" />专用上限可以低于全局上限以收紧指定物品，也可以高于全局上限作为特例；它只影响未来新流水。“最近观测”来自已持久化的 C5 + Steam 比例快照，没有可靠快照时显示为空。已开流水继续使用自己的 maxRebuyRatioAtOpen。</div>
        </article>
      </div><div class="right-column"><article class="panel settings-card time-card"><div class="card-title"><b>3</b><h2>任务时间策略</h2></div><div class="policy-form">
        <label><strong>新候选完整扫描</strong><span>基础间隔</span><div><input v-model.number="settings.timePolicy.scanMinutes" min="1" type="number" @input="changed" />分钟</div></label>
        <label><strong>普通 Steam 挂单同步</strong><span>每账号间隔</span><div><input v-model.number="settings.timePolicy.steamSyncSeconds" min="30" type="number" @input="changed" />秒</div></label>
        <label><strong>Steam 同步最长等待</strong><span>被补仓任务占用时的强制开始上限</span><div><input v-model.number="settings.timePolicy.steamSyncMaxStartLagSeconds" min="1" type="number" @input="changed" />秒</div></label>
        <label><strong>动作后快速确认</strong><span>短 / 中 / 长</span><div class="multi"><input v-for="(_,index) in settings.timePolicy.actionConfirmSeconds" :key="index" v-model.number="settings.timePolicy.actionConfirmSeconds[index]" min="2" type="number" @input="changed" /><em>秒</em></div></label>
        <label><strong>卖出证据复核</strong><span>当轮 / 后续 1 / 2 / 3 次</span><div class="multi four"><input v-for="(_,index) in settings.timePolicy.soldEvidenceMinutes" :key="index" v-model.number="settings.timePolicy.soldEvidenceMinutes[index]" min="0" type="number" @input="changed" /><em>分钟</em></div></label>
        <label><strong>补仓价格复查</strong><span>前15分 / 1小时内 / 之后</span><div class="multi"><input v-for="(_,index) in settings.timePolicy.rebuyMinutes" :key="index" v-model.number="settings.timePolicy.rebuyMinutes[index]" min="0.5" step="0.5" type="number" @input="changed" /><em>分钟</em></div></label>
        <label><strong>C5 发货确认</strong><span>前10分 / 2小时 / 12小时 / 24小时</span><div class="multi four"><input v-for="(_,index) in settings.timePolicy.deliveryMinutes" :key="index" v-model.number="settings.timePolicy.deliveryMinutes[index]" min="0.5" step="0.5" type="number" @input="changed" /><em>分钟</em></div></label>
        <label><strong>老挂单候选扫描</strong><span>发现新超过 48 小时挂单的周期</span><div><input v-model.number="settings.timePolicy.staleListedCheckHours" min="1" type="number" @input="changed" />小时</div></label>
        <label><strong>48h 老挂单复查</strong><span>保留挂单后的复查间隔</span><div><input v-model.number="settings.timePolicy.staleListedRecheckHours" min="1" type="number" @input="changed" />小时</div></label>
        <label><strong>老挂单比例容忍</strong><span>本单冻结上限额外百分点</span><div><input v-model.number="settings.timePolicy.staleListedMaxRatioTolerancePct" min="0" max="20" step="0.1" type="number" @input="changed" />百分点</div></label>
      </div><div class="policy-note"><FolioIcon name="success" :size="13" />cycleIntervalMinutes 与 listingCheckIntervalMinutes 不再参与运行；每笔任务按 nextAttemptAt 推进。</div><div class="delivery-boundary-note"><FolioIcon name="shield" :size="13" /><span><strong>12 小时从 C5 订单真实提交时间 c5OrderSubmittedAt 开始。</strong>到期后仍必须查询订单详情：明确成功才闭环，明确失败才记为 c5_failed 并创建唯一替换补仓；仍在发货或详情不可读时保持 delivery_pending。替换单同时受原失败单 actual_price（缺失才回退 expected_price）与本单 maxRebuyRatioAtOpen 两个硬上限约束。</span></div></article>
        <article class="panel settings-card scheduler-card"><div class="card-title"><b>4</b><h2>共享 Steam 请求调度</h2></div><div v-if="settings.steamScheduler" class="scheduler-grid"><div><b>MODE</b><span>所有执行器共用</span><strong>{{settings.steamScheduler.mode==="single_channel"?"单通道队列":"—"}}</strong></div><div><b>ROUTE</b><span>账号 + 路由 429 冷却</span><strong>{{durationLabel(settings.steamScheduler.accountRouteCooldownSeconds)}}</strong></div><div><b>GLOBAL</b><span>全局 429 冷却</span><strong>{{durationLabel(settings.steamScheduler.globalCooldownSeconds)}}</strong></div><div><b>DEGRADED</b><span>{{durationLabel(settings.steamScheduler.degradedAfterSeconds)}}仍未恢复</span><strong>每 {{durationLabel(settings.steamScheduler.degradedProbeSeconds)}}探测</strong></div><div><b>QUIET</b><span>Profit listings 前置安静窗口</span><strong>{{settings.steamScheduler.quietWindowEnabled?"已启用":"未启用"}}</strong></div></div><div v-else class="empty-state compact">后端暂未返回共享 Steam 调度策略。</div><p>这是后端真实固定策略，只读展示。优先级决定排队顺序，不存在四套虚构的 P0～P3 请求间隔；Retry-After、租约和熔断由共享调度器统一治理。</p></article>
      </div></section><section class="panel audit-card"><div><h2>配置审计</h2><span>所有保存都会记录修改字段、旧值、新值和时间</span></div><div v-if="settings.audit?.length" class="audit-table"><div class="audit-head"><span>时间</span><span>操作者</span><span>旧值</span><span>新值</span><span>修改字段</span><span>原因</span></div><article v-for="row in settings.audit.slice(0,8)" :key="row.id"><time>{{formatLocal(row.at)}}</time><strong>{{row.actor||"本地用户"}}</strong><code :title="JSON.stringify(row.oldValue)">{{auditText(row.oldValue)}}</code><code :title="JSON.stringify(row.newValue)">{{auditText(row.newValue)}}</code><code :title="JSON.stringify(row.diff)">{{auditText(row.diff||row.changes)}}</code><span>{{row.summary||"挂刀策略设置更新"}}</span></article></div><div v-else class="empty-state compact">暂无后端配置审计记录。</div></section><footer class="save-bar"><button class="secondary-button" type="button" :disabled="!dirty" @click="load">放弃未保存修改</button><span v-if="validation.length"><FolioIcon name="warning" :size="14" />{{validation[0]}}</span><span v-else-if="dirty">策略涉及真实执行，请谨慎核对后保存。</span><span v-else>当前页面与后端已保存策略一致。</span><button class="primary-button" type="button" :disabled="!dirty||saving||validation.length>0" @click="requestSave">保存策略</button></footer></template>
    <div v-if="confirmSave" class="modal-backdrop" @click.self="confirmSave=false"><section class="save-dialog"><span><FolioIcon :name="ratioWarning?'warning':'shield'" :size="22" /></span><h2>{{ratioWarning?"确认保存高比例规则":"确认保存挂刀策略"}}</h2><p v-if="ratioWarning">至少一条特殊箱子规则超过 75%。这会扩大未来新流水的候选和补仓边界，但不会修改已有流水冻结值。</p><p v-else>修改只影响未来新开流水和后续任务调度；已有流水的关键比例继续使用冻结值。</p><div><button class="secondary-button" @click="confirmSave=false">返回检查</button><button class="primary-button" :disabled="saving" @click="save">{{saving?"保存中…":"确认保存"}}</button></div></section></div>
  </main>
</template>

